{"thought":"I need to join expense.json with budget.csv (to get link_to_event) and event.json (to get event names). Let me write Python code to compute total costs per event.","action":"execute_python","action_input":{"code":"import json
import csv
from collections import defaultdict
with open('json/event.json', 'r') as f:
    event_data = json.load(f)
events = {rec['event_id']: rec['event_name'] for rec in event_data['records']}
budget_event_map = {}
with open('csv/budget.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        budget_event_map[row['budget_id']] = row['link_to_event']
event_costs = defaultdict(float)
with open('json/expense.json', 'r') as f:
    exp_data = json.load(f)
for exp in exp_data['records']:
    budget_id = exp.get('link_to_budget', '')
    if budget_id in budget_event_map:
        event_id = budget_event_map[budget_id]
        event_costs[event_id] += exp['cost']
min_event_id = min(event_costs, key=event_costs.get)
print(events.get(min_event_id, 'Unknown'), event_costs[min_event_id])
sorted_events = sorted(event_costs.items(), key=lambda x: x[1])
for eid, cost in sorted_events[:5]:
    print(events.get(eid, 'Unknown'), cost)"}
}}
